import{j as t,Z as n,b as i,c as h,ae as l,A as r,s as a,f as o,q as c,au as s}from"./chunks/framework.CFYg4X4w.js";const _=JSON.parse('{"title":"sylar Fiber/Scheduler/IOManager 协程运行时设计解析","description":"分析 sylar 中 Fiber、Scheduler、IOManager 与 hook 如何组成工程化协程运行时。","frontmatter":{"title":"sylar Fiber/Scheduler/IOManager 协程运行时设计解析","description":"分析 sylar 中 Fiber、Scheduler、IOManager 与 hook 如何组成工程化协程运行时。","date":"2026-06-11T00:00:00.000Z","tags":["coroutine","scheduler","epoll","C++"],"categories":["源码分析"]},"headers":[],"relativePath":"research/coroutine/sylar.md","filePath":"research/coroutine/sylar.md","lastUpdated":1782116278000}'),E={name:"research/coroutine/sylar.md"};function p(b,e,u,k,A,f){const d=n("Mermaid");return i(),h("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[e[2]||(e[2]=l('<h1 id="sylar-fiber-scheduler-iomanager-协程运行时设计解析" tabindex="-1">sylar Fiber/Scheduler/IOManager 协程运行时设计解析 <a class="header-anchor" href="#sylar-fiber-scheduler-iomanager-协程运行时设计解析" aria-label="Permalink to “sylar Fiber/Scheduler/IOManager 协程运行时设计解析”">​</a></h1><p><a href="https://github.com/sylar-yin/sylar" target="_blank" rel="noreferrer">sylar-yin/sylar</a> 是一个 C++ 服务器框架。它的协程实现不止提供上下文切换，还包含调度器、线程池、IO 事件、定时器和 hook，目标是让业务代码用同步写法获得异步 IO 的性能。</p><h2 id="总体架构" tabindex="-1">总体架构 <a class="header-anchor" href="#总体架构" aria-label="Permalink to “总体架构”">​</a></h2><p>sylar 的协程体系可以分为三层：</p><ul><li><code>Fiber</code>：协程抽象，封装 <code>ucontext_t</code>、独立栈、状态机和上下文切换。</li><li><code>Scheduler</code>：N-M 协程调度器，维护线程池和可运行任务队列。</li><li><code>IOManager</code>：继承 <code>Scheduler</code> 和 <code>TimerManager</code>，用 <code>epoll</code> 驱动 IO 协程恢复。</li></ul>',5)),(i(),r(s,null,{default:a(()=>[c(d,{id:"mermaid-29",graph:"graph%20TD%0A%20%20A%5B%E4%B8%9A%E5%8A%A1%E5%87%BD%E6%95%B0%20%2F%20Fiber%5D%20--%3E%20B%5BScheduler%3A%3Aschedule%5D%0A%20%20B%20--%3E%20C%5B%E4%BB%BB%E5%8A%A1%E9%98%9F%E5%88%97%20m_fibers%5D%0A%20%20C%20--%3E%20D%5B%E5%B7%A5%E4%BD%9C%E7%BA%BF%E7%A8%8B%20Scheduler%3A%3Arun%5D%0A%20%20D%20--%3E%20E%7B%E6%9C%89%E4%BB%BB%E5%8A%A1%3F%7D%0A%20%20E%20--%3E%7C%E6%98%AF%7C%20F%5BFiber%3A%3AswapIn%20%E6%89%A7%E8%A1%8C%5D%0A%20%20E%20--%3E%7C%E5%90%A6%7C%20G%5BIdle%20Fiber%5D%0A%20%20G%20--%3E%20H%5BIOManager%3A%3Aidle%5D%0A%20%20H%20--%3E%20I%5Bepoll_wait%20%2F%20timer%5D%0A%20%20I%20--%3E%20J%5BFdContext%3A%3AtriggerEvent%5D%0A%20%20J%20--%3E%20B%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l(`<h2 id="fiber-层" tabindex="-1">Fiber 层 <a class="header-anchor" href="#fiber-层" aria-label="Permalink to “Fiber 层”">​</a></h2><p><code>Fiber</code> 的状态包括：</p><ul><li><code>INIT</code>：初始化完成，尚未执行。</li><li><code>HOLD</code>：挂起，等待外部事件唤醒。</li><li><code>EXEC</code>：正在执行。</li><li><code>TERM</code>：执行结束。</li><li><code>READY</code>：可执行，等待调度。</li><li><code>EXCEPT</code>：执行异常。</li></ul><p>与共享栈实现不同，sylar 为每个普通协程分配独立栈：</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m_stack </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> StackAllocator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Alloc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m_stacksize);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m_ctx.uc_stack.ss_sp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> m_stack;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m_ctx.uc_stack.ss_size </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> m_stacksize;</span></span></code></pre></div><p>这样切换时不需要复制栈，但每个协程都会长期占用自己的栈空间。</p><h3 id="关键函数" tabindex="-1">关键函数 <a class="header-anchor" href="#关键函数" aria-label="Permalink to “关键函数”">​</a></h3><h4 id="fiber-fiber" tabindex="-1"><code>Fiber::Fiber()</code> <a class="header-anchor" href="#fiber-fiber" aria-label="Permalink to “Fiber::Fiber()”">​</a></h4><p>创建当前线程的主协程。主协程不分配独立栈，使用线程原生栈，并通过 <code>SetThis(this)</code> 设为当前协程。</p><h4 id="fiber-fiber-std-function-void-cb" tabindex="-1"><code>Fiber::Fiber(std::function&lt;void()&gt; cb, ...)</code> <a class="header-anchor" href="#fiber-fiber-std-function-void-cb" aria-label="Permalink to “Fiber::Fiber(std::function&lt;void()&gt; cb, ...)”">​</a></h4><p>创建普通业务协程：</p><ul><li>分配独立栈。</li><li><code>getcontext</code> 初始化上下文。</li><li>设置 <code>uc_stack</code>。</li><li>根据 <code>use_caller</code> 选择入口 <code>MainFunc</code> 或 <code>CallerMainFunc</code>。</li></ul><h4 id="fiber-swapin-fiber-swapout" tabindex="-1"><code>Fiber::swapIn</code> / <code>Fiber::swapOut</code> <a class="header-anchor" href="#fiber-swapin-fiber-swapout" aria-label="Permalink to “Fiber::swapIn / Fiber::swapOut”">​</a></h4><p><code>swapIn</code> 从调度协程切入当前业务协程；<code>swapOut</code> 从当前业务协程切回调度协程。调度器随后根据协程状态决定是否重新入队。</p><h4 id="fiber-yieldtoready-fiber-yieldtohold" tabindex="-1"><code>Fiber::YieldToReady</code> / <code>Fiber::YieldToHold</code> <a class="header-anchor" href="#fiber-yieldtoready-fiber-yieldtohold" aria-label="Permalink to “Fiber::YieldToReady / Fiber::YieldToHold”">​</a></h4><ul><li><code>YieldToReady</code>：让出后仍希望继续运行，状态改为 <code>READY</code>。</li><li><code>YieldToHold</code>：让出并等待事件，通常由 IO、定时器或外部逻辑唤醒。</li></ul><h4 id="fiber-mainfunc" tabindex="-1"><code>Fiber::MainFunc</code> <a class="header-anchor" href="#fiber-mainfunc" aria-label="Permalink to “Fiber::MainFunc”">​</a></h4><p>普通协程入口：执行业务回调，正常结束置为 <code>TERM</code>，异常置为 <code>EXCEPT</code>，最后 <code>swapOut</code> 回到调度协程。</p><h2 id="scheduler-层" tabindex="-1">Scheduler 层 <a class="header-anchor" href="#scheduler-层" aria-label="Permalink to “Scheduler 层”">​</a></h2><p><code>Scheduler</code> 是 N-M 调度器：N 个线程调度 M 个协程或回调。</p><p>核心成员：</p><ul><li><code>m_threads</code>：工作线程数组。</li><li><code>m_fibers</code>：待执行任务队列，任务可以是 <code>Fiber::ptr</code> 或 callback。</li><li><code>m_rootFiber</code>：当 <code>use_caller = true</code> 时，调用线程也作为调度线程。</li><li><code>m_activeThreadCount</code> / <code>m_idleThreadCount</code>：线程状态计数。</li></ul><h3 id="调度循环" tabindex="-1">调度循环 <a class="header-anchor" href="#调度循环" aria-label="Permalink to “调度循环”">​</a></h3><p><code>Scheduler::run</code> 是调度核心：</p>`,24)),(i(),r(s,null,{default:a(()=>[c(d,{id:"mermaid-176",graph:"flowchart%20TD%0A%20%20A%5Brun%20%E5%BC%80%E5%A7%8B%5D%20--%3E%20B%5Bset_hook_enable%20true%5D%0A%20%20B%20--%3E%20C%5B%E5%88%9B%E5%BB%BA%20idle_fiber%5D%0A%20%20C%20--%3E%20D%5B%E4%BB%8E%20m_fibers%20%E5%8F%96%E4%BB%BB%E5%8A%A1%5D%0A%20%20D%20--%3E%20E%7B%E4%BB%BB%E5%8A%A1%E5%AD%98%E5%9C%A8%3F%7D%0A%20%20E%20--%3E%7CFiber%7C%20F%5BswapIn%5D%0A%20%20E%20--%3E%7CCallback%7C%20G%5B%E5%8C%85%E8%A3%85%2F%E5%A4%8D%E7%94%A8%20cb_fiber%20%E5%90%8E%20swapIn%5D%0A%20%20E%20--%3E%7C%E6%97%A0%E4%BB%BB%E5%8A%A1%7C%20H%5Bidle_fiber%20swapIn%5D%0A%20%20F%20--%3E%20I%7B%E7%8A%B6%E6%80%81%7D%0A%20%20G%20--%3E%20I%0A%20%20I%20--%3E%7CREADY%7C%20J%5B%E9%87%8D%E6%96%B0%20schedule%5D%0A%20%20I%20--%3E%7CTERM%2FEXCEPT%7C%20K%5B%E5%9B%9E%E6%94%B6%2F%E9%87%8D%E7%BD%AE%5D%0A%20%20I%20--%3E%7C%E5%85%B6%E4%BB%96%7C%20L%5B%E7%BD%AE%E4%B8%BA%20HOLD%5D%0A%20%20J%20--%3E%20D%0A%20%20K%20--%3E%20D%0A%20%20L%20--%3E%20D%0A%20%20H%20--%3E%20D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=l('<h3 id="scheduler-schedule" tabindex="-1"><code>Scheduler::schedule</code> <a class="header-anchor" href="#scheduler-schedule" aria-label="Permalink to “Scheduler::schedule”">​</a></h3><p>将协程或函数加入任务队列。可指定线程 id，<code>-1</code> 表示任意线程。入队后如果需要唤醒空闲线程，会调用 <code>tickle</code>。</p><h2 id="iomanager-层" tabindex="-1">IOManager 层 <a class="header-anchor" href="#iomanager-层" aria-label="Permalink to “IOManager 层”">​</a></h2><p><code>IOManager</code> 在调度器基础上加入 epoll 和 timer。</p><p>关键设计：</p><ul><li><code>epoll_create</code> 创建 epoll 实例。</li><li>pipe 作为 tickle 机制，用于唤醒阻塞在 <code>epoll_wait</code> 的线程。</li><li><code>FdContext</code> 保存每个 fd 的 READ/WRITE 事件上下文。</li><li>事件上下文保存对应的 scheduler、fiber 或 callback。</li></ul><h3 id="iomanager-addevent" tabindex="-1"><code>IOManager::addEvent</code> <a class="header-anchor" href="#iomanager-addevent" aria-label="Permalink to “IOManager::addEvent”">​</a></h3><p>注册 fd 事件：</p><ul><li>找到或扩容 <code>FdContext</code>。</li><li>根据已有事件选择 <code>EPOLL_CTL_ADD</code> 或 <code>EPOLL_CTL_MOD</code>。</li><li>使用 <code>EPOLLET</code> 边缘触发。</li><li>保存当前调度器。</li><li>如果传入 callback，则保存 callback；否则保存当前协程。</li></ul><p>业务协程注册事件后通常会 yield。事件到达后，IOManager 再把它加入调度队列。</p><h3 id="iomanager-idle" tabindex="-1"><code>IOManager::idle</code> <a class="header-anchor" href="#iomanager-idle" aria-label="Permalink to “IOManager::idle”">​</a></h3><p>空闲协程负责等待 IO：</p><ul><li>根据最近定时器计算 <code>epoll_wait</code> 超时时间。</li><li>等待 fd 事件或 tickle pipe。</li><li>将过期定时器回调加入调度队列。</li><li>将 READ/WRITE 事件转换为协程或 callback 调度。</li><li>处理完后 <code>swapOut</code>，让调度器运行被唤醒的任务。</li></ul><h3 id="fdcontext-triggerevent" tabindex="-1"><code>FdContext::triggerEvent</code> <a class="header-anchor" href="#fdcontext-triggerevent" aria-label="Permalink to “FdContext::triggerEvent”">​</a></h3><p>触发某个 fd 事件：</p><ul><li>从当前事件集合中移除该事件。</li><li>如果保存的是 callback，则调度 callback。</li><li>如果保存的是 fiber，则调度 fiber。</li><li>清理事件上下文。</li></ul><h2 id="hook-的作用" tabindex="-1">hook 的作用 <a class="header-anchor" href="#hook-的作用" aria-label="Permalink to “hook 的作用”">​</a></h2><p><code>Scheduler::run</code> 会调用 <code>set_hook_enable(true)</code>。hook 层通常拦截 <code>sleep/read/write/connect</code> 等阻塞调用，把它们转换为协程友好的异步流程：</p><ol><li>fd 设置为非阻塞。</li><li>操作未就绪时注册 READ/WRITE 事件。</li><li>当前协程 yield。</li><li>IO 就绪或超时后恢复协程。</li><li>继续执行原系统调用。</li></ol><p>这样业务代码看起来是同步阻塞写法，但实际阻塞的是协程而不是线程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>sylar 的协程实现已经是工程化运行时：<code>Fiber</code> 解决执行上下文，<code>Scheduler</code> 解决任务分发，<code>IOManager</code> 解决 IO 等待和唤醒，hook 解决同步 API 到异步调度的转换。</p>',22))])}const g=t(E,[["render",p]]);export{_ as __pageData,g as default};
